import java.awt.*;import java.awt.image.*;import java.io.*;import javax.imageio.ImageIO;import com.koios.client.arpg.*;import com.koios.client.graphic.*;import com.koios.client.cache.Decompressor;import com.koios.client.stream.StreamLoader;
/** Original Exile artwork, cached cover scaling, native form and shared input geometry. No authentication. */
public final class ExileLoginCheck {
 static int checks;static void check(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}
 private static int labelTop(TextDrawingArea font,String text,int baseline){int top=Integer.MAX_VALUE;for(char c:text.toCharArray())for(int i=0;i<font.aByteArrayArray1491[c].length;i++)if(font.aByteArrayArray1491[c][i]!=0)top=Math.min(top,baseline-font.anInt1497+font.anIntArray1495[c]+i/font.anIntArray1492[c]);return top;}
 public static void main(String[]args)throws Exception{File source=new File("../koios-cache/arpg-art/exile-login-v1.png");ExileLogin.Backdrop backdrop=new ExileLogin.Backdrop(source);try(RandomAccessFile data=new RandomAccessFile("../koios-cache/main_file_cache.dat","r");RandomAccessFile index=new RandomAccessFile("../koios-cache/main_file_cache.idx0","r")){TextDrawingArea font=new TextDrawingArea(false,"p12_full",new StreamLoader(new Decompressor(data,index,1).decompress(1)));for(int[] size:new int[][]{{765,503},{1280,720},{1920,1080}}){Sprite bg=backdrop.frame(size[0],size[1]);check(backdrop.hasArt(),"Original background artwork loads");int builds=backdrop.builds();for(int i=0;i<1000;i++)check(backdrop.frame(size[0],size[1])==bg,"Same viewport reuses cached raster without per-frame image allocations");check(backdrop.builds()==builds,"No repeated cover composition");ExileLogin.Layout l=ExileLogin.layout(size[0],size[1]);check(l==ExileLogin.layout(size[0],size[1]),"Shared login layout is cached");for(Rectangle rect:new Rectangle[]{l.account,l.password,l.remember,l.submit}){check(rect.x>=0&&rect.y>=0&&rect.x+rect.width<=size[0]&&rect.y+rect.height<=size[1],"Every painted/input rectangle fits viewport");check(rect.contains(rect.x,rect.y)&&rect.contains(rect.x+rect.width-1,rect.y+rect.height-1)&&!rect.contains(rect.x+rect.width,rect.y),"Half-open exact input target bounds");}check(l.account.y+l.account.height<=labelTop(font,"PASSWORD",l.password.y-6),"Password label has clear native-font space below account field");check(!l.account.intersects(l.password)&&!l.password.intersects(l.remember)&&!l.remember.intersects(l.submit),"Login targets never overlap");check(l.submit.width==147&&l.submit.height==44,"Submit target matches actual painted button rather than old276px field");BufferedImage image=new BufferedImage(size[0],size[1],BufferedImage.TYPE_INT_RGB);DrawingArea.initDrawingArea(size[1],size[0],((DataBufferInt)image.getRaster().getDataBuffer()).getData());bg.drawSprite(0,0);ExileLogin.chrome(font,l,l.submit.x+5,l.submit.y+5,true,0);font.method389(true,l.account.x+6,ExileTheme.TEXT,"QA EXILE",l.account.y+22);font.method389(true,l.password.x+6,ExileTheme.TEXT,"********",l.password.y+23);font.drawText(ExileTheme.MUTED,size[0]/2,"Welcome to Exile",l.y+200,true);ImageIO.write(image,"png",new File("build/exile-login-"+size[0]+".png"));}ExileLogin.Backdrop missing=new ExileLogin.Backdrop(new File("build/does-not-exist-login-art.png"));Sprite fallback=missing.frame(765,503);check(!missing.hasArt()&&fallback!=null&&fallback.myPixels.length==765*503,"Missing optional art preserves readable complete charcoal/wordmark fallback");check(missing.frame(765,503)==fallback,"Fallback is cached too");BufferedImage image=new BufferedImage(765,503,BufferedImage.TYPE_INT_RGB);DrawingArea.initDrawingArea(503,765,((DataBufferInt)image.getRaster().getDataBuffer()).getData());fallback.drawSprite(0,0);ExileLogin.chrome(font,ExileLogin.layout(765,503),0,0,false,0);ImageIO.write(image,"png",new File("build/exile-login-fallback.png"));}System.out.println("Passed "+checks+" Exile native login/art/cache/layout checks.");}
}
